import sys
import threading

def main():
    import sys
    import threading

    def dfs(node, parent):
        max_sum = 0
        for neighbor in graph[node]:
            if neighbor != parent:
                max_sum += dfs(neighbor, node)
        return max_sum + values[node]

    def solve():
        n = int(sys.stdin.readline())
        values = list(map(int, sys.stdin.readline().split()))
        graph = [[] for _ in range(n)]
        for _ in range(n - 1):
            u, v = map(int, sys.stdin.readline().split())
            u -= 1
            v -= 1
            graph[u].append(v)
            graph[v].append(u)

        total_sum = sum(values)
        max_sum = dfs(0, -1)

        if max_sum * 2 > total_sum:
            print(total_sum)
        else:
            print("Impossible")

    threading.Thread(target=solve).start()

if __name__ == "__main__":
    main()
